from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"expected exactly one match in {path}: found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


# Keep calendar-day streak calculation pure and independently testable.
core = ROOT / "rollpig_core.py"
replace_once(
    core,
    '''from __future__ import annotations\n\nimport ipaddress\nimport re\n''',
    '''from __future__ import annotations\n\nimport datetime\nimport ipaddress\nimport re\nfrom typing import Any, Mapping\n''',
)
core_text = core.read_text(encoding="utf-8")
helper = '''\n\ndef consecutive_duplicate_day_streak(\n    history: Mapping[str, Any] | None,\n    collection: Mapping[str, Any] | None,\n    storage_id: str,\n    before_date: datetime.date,\n) -> int:\n    """Count adjacent prior calendar days whose completed draw was already unlocked.\n\n    A missing day breaks the chain. If a day's visible record was replaced by the\n    special ``eaten`` state, ``eaten_originals`` is used so the original draw still\n    determines whether that day was a duplicate.\n    """\n    history_map = history if isinstance(history, Mapping) else {}\n    daily = history_map.get("daily")\n    if not isinstance(daily, Mapping):\n        return 0\n\n    user = collection if isinstance(collection, Mapping) else {}\n    pigs = user.get("pigs")\n    if not isinstance(pigs, Mapping):\n        return 0\n\n    key = str(storage_id or "")\n    if not key:\n        return 0\n\n    streak = 0\n    cursor = before_date - datetime.timedelta(days=1)\n    while True:\n        day = daily.get(cursor.isoformat())\n        if not isinstance(day, Mapping):\n            break\n        records = day.get("records")\n        if not isinstance(records, Mapping):\n            break\n        pig_id = str(records.get(key) or "")\n        if pig_id == "eaten":\n            originals = day.get("eaten_originals")\n            pig_id = (\n                str(originals.get(key) or "")\n                if isinstance(originals, Mapping)\n                else ""\n            )\n        if not pig_id:\n            break\n\n        record = pigs.get(pig_id)\n        if not isinstance(record, Mapping):\n            break\n        first_unlocked = str(record.get("first_unlocked") or "")\n        try:\n            first_unlocked_date = datetime.date.fromisoformat(first_unlocked)\n        except ValueError:\n            break\n        if first_unlocked_date >= cursor:\n            break\n\n        streak += 1\n        cursor -= datetime.timedelta(days=1)\n\n    return streak\n'''
if "def consecutive_duplicate_day_streak(" in core_text:
    raise RuntimeError("calendar streak helper already exists")
core.write_text(core_text.rstrip() + helper + "\n", encoding="utf-8")


# Import the pure helper and provide the real adjacent-day streak to DrawService.
main = ROOT / "main.py"
replace_once(
    main,
    '''    from .services import DrawService, RoastService\n    from .storage import StorageManager, StorageMigrationError\n''',
    '''    from .rollpig_core import consecutive_duplicate_day_streak\n    from .services import DrawService, RoastService\n    from .storage import StorageManager, StorageMigrationError\n''',
)
replace_once(
    main,
    '''    from services import DrawService, RoastService\n    from storage import StorageManager, StorageMigrationError\n''',
    '''    from rollpig_core import consecutive_duplicate_day_streak\n    from services import DrawService, RoastService\n    from storage import StorageManager, StorageMigrationError\n''',
)
replace_once(
    main,
    '''    def _choose_daily_pig(self, user_id: str) -> dict:\n        """Delegate pure pity/selection policy to DrawService."""\n        return self.draw_service.choose(\n            self.pig_list,\n            self._get_user_collection(user_id),\n        )\n''',
    '''    def _choose_daily_pig(self, user_id: str) -> dict:\n        """Delegate pure pity/selection policy to DrawService."""\n        collection = self._get_user_collection(user_id)\n        draw_context = dict(collection) if isinstance(collection, dict) else {}\n        draw_context["daily_duplicate_streak"] = consecutive_duplicate_day_streak(\n            self.history,\n            draw_context,\n            self._storage_user_key(str(user_id)),\n            self._today(),\n        )\n        return self.draw_service.choose(self.pig_list, draw_context)\n''',
)


# Daily bonus now uses a distinct calendar streak; legacy duplicate_streak remains untouched.
draw_service = '''from __future__ import annotations\n\nimport random\nfrom dataclasses import dataclass\nfrom typing import Any, Mapping, Sequence\n\n\n@dataclass(frozen=True)\nclass DrawService:\n    """Pure daily-draw selection policy, independent from persistence and AstrBot."""\n\n    enable_new_pig_pity: bool = True\n    pity_step_percent: int = 15\n    enable_daily_duplicate_pity: bool = True\n    daily_duplicate_pity_start_day: int = 2\n    daily_duplicate_pity_step_percent: int = 5\n    daily_duplicate_pity_max_percent: int = 15\n    max_pity_percent: int = 80\n\n    @staticmethod\n    def _streak(collection: Mapping[str, Any] | None, key: str) -> int:\n        user = collection if isinstance(collection, Mapping) else {}\n        try:\n            return max(0, int(user.get(key, 0) or 0))\n        except (TypeError, ValueError):\n            return 0\n\n    def pity_chance(self, collection: Mapping[str, Any] | None) -> float:\n        """Return the reroll-to-unseen probability for a duplicate candidate.\n\n        ``duplicate_streak`` keeps the legacy consecutive-draw behavior.\n        ``daily_duplicate_streak`` counts only adjacent completed calendar days, so\n        skipping a day resets the new fatigue bonus without changing legacy pity.\n        """\n        legacy_streak = self._streak(collection, "duplicate_streak")\n        daily_streak = self._streak(collection, "daily_duplicate_streak")\n\n        base_percent = 0\n        if self.enable_new_pig_pity:\n            base_percent = legacy_streak * max(0, int(self.pity_step_percent))\n\n        daily_bonus_percent = 0\n        if self.enable_daily_duplicate_pity:\n            start_day = min(7, max(2, int(self.daily_duplicate_pity_start_day)))\n            step_percent = max(0, int(self.daily_duplicate_pity_step_percent))\n            bonus_cap = max(0, int(self.daily_duplicate_pity_max_percent))\n            current_duplicate_day = daily_streak + 1\n            if current_duplicate_day >= start_day:\n                bonus_layers = current_duplicate_day - start_day + 1\n                daily_bonus_percent = min(bonus_cap, bonus_layers * step_percent)\n\n        total_percent = min(\n            max(0, int(self.max_pity_percent)),\n            base_percent + daily_bonus_percent,\n        )\n        return total_percent / 100\n\n    def choose(\n        self,\n        pigs: Sequence[Mapping[str, Any]],\n        collection: Mapping[str, Any] | None,\n        *,\n        rng: Any = random,\n    ) -> dict[str, Any]:\n        if not pigs:\n            raise ValueError("pig catalog is empty")\n        chosen = dict(rng.choice(pigs))\n        if not (self.enable_new_pig_pity or self.enable_daily_duplicate_pity):\n            return chosen\n\n        user = collection if isinstance(collection, Mapping) else {}\n        unlocked_raw = user.get("pigs")\n        unlocked = set(unlocked_raw) if isinstance(unlocked_raw, Mapping) else set()\n        unseen = [pig for pig in pigs if str(pig.get("id") or "") not in unlocked]\n        chosen_id = str(chosen.get("id") or "")\n        if not unseen or chosen_id not in unlocked:\n            return chosen\n\n        chance = self.pity_chance(user)\n        return dict(rng.choice(unseen)) if rng.random() < chance else chosen\n'''
(ROOT / "services" / "draw_service.py").write_text(draw_service, encoding="utf-8")


# Clarify calendar adjacency in documentation.
config_doc = ROOT / "docs" / "CONFIGURATION.md"
replace_once(
    config_doc,
    '''`duplicate_streak` 只會在真正完成一個新的每日抽取後更新，因此同一天反覆查看 `/今日小豬` 不會堆疊跨日層數。抽到未解鎖小豬時，連續重複會立即歸零。\n\n預設值下，若下一次候選仍是已解鎖小豬：第 2 個連續重複日的額外跨日加成為 `+5%`，第 3 日為 `+10%`，第 4 日起封頂 `+15%`。它會與原 `duplicate_streak × pity_step_percent` 相加，但最終重抽未解鎖小豬的概率仍不超過 `80%`。\n''',
    '''跨日疲勞層數會從抽取歷史按自然日向前回溯：只有「昨天也完成抽取，而且昨天抽到的小豬在昨天之前就已解鎖」才會延續。中間漏抽一天、昨天抽中新豬，或沒有有效抽取記錄，都會讓跨日疲勞層數歸零。同一天反覆查看 `/今日小豬` 不會增加層數；原本的 `duplicate_streak` 則保持既有的連續抽取語義，不因這次改動而改寫。\n\n預設值下，若下一次候選仍是已解鎖小豬：第 2 個相鄰重複日的額外跨日加成為 `+5%`，第 3 日為 `+10%`，第 4 日起封頂 `+15%`。它會與原 `duplicate_streak × pity_step_percent` 相加，但最終重抽未解鎖小豬的概率仍不超過 `80%`。\n''',
)


# Focused tests for both the pure calendar streak and combined probability behavior.
test_path = ROOT / "tests" / "test_draw_service_pity.py"
test_path.write_text(
    '''from __future__ import annotations\n\nimport datetime\n\nimport pytest\n\nfrom rollpig_core import consecutive_duplicate_day_streak\nfrom services.draw_service import DrawService\n\n\nclass StubRng:\n    def __init__(self, first_choice, random_value: float):\n        self.first_choice = first_choice\n        self.random_value = random_value\n        self.choice_calls = 0\n\n    def choice(self, items):\n        self.choice_calls += 1\n        if self.choice_calls == 1:\n            return self.first_choice\n        return items[0]\n\n    def random(self):\n        return self.random_value\n\n\ndef test_legacy_pity_is_unchanged_when_daily_bonus_is_disabled():\n    service = DrawService(\n        enable_new_pig_pity=True,\n        pity_step_percent=15,\n        enable_daily_duplicate_pity=False,\n    )\n    assert service.pity_chance({"duplicate_streak": 0}) == pytest.approx(0.0)\n    assert service.pity_chance({"duplicate_streak": 1}) == pytest.approx(0.15)\n    assert service.pity_chance({"duplicate_streak": 2}) == pytest.approx(0.30)\n\n\ndef test_daily_bonus_starts_on_second_adjacent_duplicate_day():\n    service = DrawService()\n    assert service.pity_chance(\n        {"duplicate_streak": 0, "daily_duplicate_streak": 0}\n    ) == pytest.approx(0.0)\n    assert service.pity_chance(\n        {"duplicate_streak": 1, "daily_duplicate_streak": 1}\n    ) == pytest.approx(0.20)\n    assert service.pity_chance(\n        {"duplicate_streak": 2, "daily_duplicate_streak": 2}\n    ) == pytest.approx(0.40)\n    assert service.pity_chance(\n        {"duplicate_streak": 3, "daily_duplicate_streak": 3}\n    ) == pytest.approx(0.60)\n    assert service.pity_chance(\n        {"duplicate_streak": 4, "daily_duplicate_streak": 4}\n    ) == pytest.approx(0.75)\n\n\ndef test_calendar_gap_resets_only_new_bonus_not_legacy_pity():\n    service = DrawService()\n    assert service.pity_chance(\n        {"duplicate_streak": 3, "daily_duplicate_streak": 0}\n    ) == pytest.approx(0.45)\n\n\ndef test_daily_bonus_has_independent_switch_and_can_work_without_legacy_pity():\n    service = DrawService(\n        enable_new_pig_pity=False,\n        enable_daily_duplicate_pity=True,\n        daily_duplicate_pity_start_day=2,\n        daily_duplicate_pity_step_percent=5,\n        daily_duplicate_pity_max_percent=15,\n    )\n    assert service.pity_chance({"daily_duplicate_streak": 0}) == pytest.approx(0.0)\n    assert service.pity_chance({"daily_duplicate_streak": 1}) == pytest.approx(0.05)\n    assert service.pity_chance({"daily_duplicate_streak": 3}) == pytest.approx(0.15)\n    assert service.pity_chance({"daily_duplicate_streak": 20}) == pytest.approx(0.15)\n\n\ndef test_combined_pity_never_exceeds_eighty_percent():\n    service = DrawService()\n    assert service.pity_chance(\n        {"duplicate_streak": 20, "daily_duplicate_streak": 20}\n    ) == pytest.approx(0.80)\n\n\ndef test_calendar_streak_requires_adjacent_days_and_preexisting_unlock():\n    today = datetime.date(2026, 8, 14)\n    collection = {\n        "pigs": {\n            "owned": {"first_unlocked": "2026-08-01", "count": 5},\n            "newer": {"first_unlocked": "2026-08-12", "count": 1},\n        }\n    }\n    history = {\n        "daily": {\n            "2026-08-13": {"records": {"u": "owned"}},\n            "2026-08-12": {"records": {"u": "owned"}},\n            "2026-08-11": {"records": {"u": "owned"}},\n        }\n    }\n    assert consecutive_duplicate_day_streak(history, collection, "u", today) == 3\n\n    history["daily"].pop("2026-08-13")\n    assert consecutive_duplicate_day_streak(history, collection, "u", today) == 0\n\n\ndef test_calendar_streak_stops_when_previous_day_was_a_new_unlock():\n    today = datetime.date(2026, 8, 14)\n    collection = {"pigs": {"new": {"first_unlocked": "2026-08-13", "count": 1}}}\n    history = {"daily": {"2026-08-13": {"records": {"u": "new"}}}}\n    assert consecutive_duplicate_day_streak(history, collection, "u", today) == 0\n\n\ndef test_eaten_visible_state_uses_original_draw_for_calendar_streak():\n    today = datetime.date(2026, 8, 14)\n    collection = {"pigs": {"owned": {"first_unlocked": "2026-08-01", "count": 4}}}\n    history = {\n        "daily": {\n            "2026-08-13": {\n                "records": {"u": "eaten"},\n                "eaten_originals": {"u": "owned"},\n            }\n        }\n    }\n    assert consecutive_duplicate_day_streak(history, collection, "u", today) == 1\n\n\ndef test_choose_rerolls_duplicate_to_unseen_when_combined_pity_hits():\n    duplicate = {"id": "owned", "name": "Owned"}\n    unseen = {"id": "new", "name": "New"}\n    service = DrawService()\n    rng = StubRng(duplicate, random_value=0.19)\n\n    chosen = service.choose(\n        [duplicate, unseen],\n        {\n            "pigs": {"owned": {"count": 1}},\n            "duplicate_streak": 1,\n            "daily_duplicate_streak": 1,\n        },\n        rng=rng,\n    )\n\n    assert chosen["id"] == "new"\n\n\ndef test_choose_keeps_duplicate_when_roll_misses_combined_pity():\n    duplicate = {"id": "owned", "name": "Owned"}\n    unseen = {"id": "new", "name": "New"}\n    service = DrawService()\n    rng = StubRng(duplicate, random_value=0.20)\n\n    chosen = service.choose(\n        [duplicate, unseen],\n        {\n            "pigs": {"owned": {"count": 1}},\n            "duplicate_streak": 1,\n            "daily_duplicate_streak": 1,\n        },\n        rng=rng,\n    )\n\n    assert chosen["id"] == "owned"\n''',
    encoding="utf-8",
)
